python -c "
import wandb; api = wandb.Api()
runs = api.runs('wandb-applied-ai-team/kagent-v1', filters={'state': 'finished'}, order='+summary_metrics.val/loss', per_page=5)
for r in runs[:5]:
    vl = r.summary.get('val/loss', '?')
    print(f'{r.name:50s} val/loss={vl}')
    cfg = dict(r.config)
    for k in ['hidden', 'n_blocks', 'lr', 'epochs', 'ema_decay', 'val_every', 'compile', 'surf_weight', 'batch_size', 'accum_steps', 'n_params']:
        v = cfg.get(k)
        if v is not None:
            print(f'  {k}={v}')
    print()
" 2>/dev/null
